    val pyramidFactory = new PyramidFactory(
      openSearchClient,
      openSearchCollectionId = "urn:eop:VITO:TERRASCOPE_S3_SY_2_VG1_V1",
      openSearchLinkTitles = bands,
      rootPath = null,
